   const trend=ready&&delta!==0?'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="'+(delta>0?'M2 14l5-5 4 3 6-8M12 4h5v5':'M2 6l5 5 4-3 6 8M12 16h5v-5')+'"/></svg>':'';
